const enc=new TextEncoder(),b64=b=>btoa(String.fromCharCode(...new Uint8Array(b))).replaceAll("=","").replaceAll("+","-").replaceAll("/","_");
async function hash(p,s){const k=await crypto.subtle.importKey("raw",enc.encode(p),"PBKDF2",false,["deriveBits"]);return b64(await crypto.subtle.deriveBits({name:"PBKDF2",salt:enc.encode(s),iterations:210000,hash:"SHA-256"},k,256))}
export async function onRequestPost({request,env}){if(request.headers.get("Authorization")!=="Bearer "+env.JELHR_BOOTSTRAP_TOKEN)return Response.json({error:"Not authorized"},{status:401});if(!env.DB||!env.JELHR_ADMIN_EMAIL||!env.JELHR_ADMIN_PASSWORD||!env.JELHR_JWT_SECRET||env.JELHR_JWT_SECRET.length<32||!env.JELHR_BOOTSTRAP_TOKEN)return Response.json({error:"Bootstrap secrets are not configured"}, {status:503});const count=await env.DB.prepare("SELECT COUNT(*) n FROM users WHERE role IN ('owner','admin')").first();if(count.n>0)return Response.json({error:"Initial administrator is already provisioned"}, {status:409});const email=String(env.JELHR_ADMIN_EMAIL).toLowerCase().trim(),password=String(env.JELHR_ADMIN_PASSWORD);if(!email.includes("@")||!email.split("@")[1]?.includes(".")||password.length<14)return Response.json({error:"Configure a valid admin email and a password of at least 14 characters"}, {status:503});const body=await request.json().catch(()=>({}));if(body.confirmation!=="PROVISION INITIAL ADMIN")return Response.json({error:"Explicit bootstrap confirmation required"}, {status:400});const orgId=crypto.randomUUID(),userId=crypto.randomUUID(),salt=b64(crypto.getRandomValues(new Uint8Array(24)));await env.DB.prepare("INSERT INTO organizations(id,name,slug) VALUES(?,?,?)").bind(orgId,"JelHR Organization","jelhr-"+orgId.slice(0,8)).run();await env.DB.prepare("INSERT INTO users(id,organization_id,email,display_name,password_hash,password_salt,role,status) VALUES(?,?,?,?,?,?,?,?)").bind(userId,orgId,email,"JelHR Administrator",await hash(password,salt),salt,"owner","active").run();return Response.json({ok:true,message:"Initial administrator provisioned. Remove bootstrap credentials from the runtime after provisioning."},{headers:{"Cache-Control":"no-store"}})}
